<template>
  <div class="workbench-view">
    <div class="batch-page">
      <section class="batch-hero">
        <div><span class="kicker">从一条提示词开始</span><h2>把重复劳动交给队列</h2><p>每行一个提示词，或让系统按同一目标生成多份变体。并发上限由你设置，也可从 1 开始逐步探索；可随时暂停后续提交，已经提交的任务会自然收口。</p></div>
        <div class="batch-hero-stat"><strong v-if="activeBatch">{{ activeBatch.completed }}/{{ activeBatch.total }}</strong><strong v-else>—</strong><span>{{ activeBatch ? '当前批次已完成' : '还没有活动批次' }}</span></div>
      </section>
      <section class="source-paths" aria-label="批量任务入口">
        <div><span class="path-icon"><el-icon><EditPen /></el-icon></span><span><strong>已经有每项提示词</strong><small>在下方直接排队，适合批量变体、分镜图和同规格视频。</small></span></div>
        <router-link to="/asset-import"><span class="path-icon"><el-icon><FolderOpened /></el-icon></span><span><strong>有几百或几千个素材文件</strong><small>先让 Codex 识别文件、产品和用途，再生成逐项方案。</small></span><el-icon><ArrowRight /></el-icon></router-link>
        <router-link to="/codex-console"><span class="path-icon"><el-icon><MagicStick /></el-icon></span><span><strong>只有一句目标</strong><small>让 Codex 先研究、规划并选择图片、视频、剪辑或 Blender 工具。</small></span><el-icon><ArrowRight /></el-icon></router-link>
      </section>
      <div class="batch-grid">
        <section class="panel setup-panel">
          <header class="panel-heading"><div><span class="kicker">1 / 设置任务</span><h3>告诉 Codex 要批量做什么</h3></div><span class="hint">不会自动覆盖已有项目</span></header>
          <el-tabs v-model="form.kind" stretch><el-tab-pane label="图片" name="image" /><el-tab-pane label="视频" name="video" /></el-tabs>
          <label class="field-label">共同提示词</label><el-input v-model="form.prompt" type="textarea" :rows="4" placeholder="例如：为这款白色咖啡杯制作一张干净的电商主图，柔和侧光，留出标题空间" />
          <div class="field-note">每一项都会继承这段描述；如果下面填写了逐项提示词，则逐项内容优先。</div>
          <label class="field-label">逐项提示词（可选）</label><el-input v-model="form.lines" type="textarea" :rows="6" placeholder="一行一个变体，例如：&#10;厨房台面场景&#10;办公桌场景&#10;户外野餐场景" />
          <div class="field-note">没有逐项提示词时，用“生成数量”自动复制共同提示词并编号。</div>
          <div class="form-row"><div><label class="field-label">生成数量</label><el-input-number v-model="form.count" :min="1" :max="10000" controls-position="right" /><div class="field-note">最多 10,000 项，队列按页显示</div></div><div><label class="field-label">并发数量</label><el-input-number v-model="form.concurrency" :min="1" :precision="0" controls-position="right" @change="saveConcurrency" /><div class="field-note">填写正整数，按模型和机器能力设置上限</div></div></div>
          <div class="form-row"><div><label class="field-label">模型（可选）</label><el-select v-model="form.model" clearable filterable allow-create default-first-option placeholder="使用系统默认，或输入模型名" class="full"><el-option v-for="item in modelOptions" :key="item.value" :label="item.label" :value="item.value" /></el-select></div><div><label class="field-label">批次名称</label><el-input v-model="form.title" placeholder="例如：夏季产品图第一批" /></div></div>
          <div class="advanced-box"><div class="advanced-title">常用参数 <small>会原样交给现有图片/视频接口</small></div><div class="form-row"><div><label class="field-label">画幅</label><el-select v-model="form.settings.aspect_ratio" class="full"><el-option label="16:9" value="16:9" /><el-option label="9:16" value="9:16" /><el-option label="1:1" value="1:1" /><el-option label="4:3" value="4:3" /></el-select></div><div v-if="form.kind === 'video'"><label class="field-label">时长（秒）</label><el-input-number v-model="form.settings.duration" :min="1" :max="60" controls-position="right" /></div></div></div>
          <div class="advanced-box"><el-switch v-model="form.adaptive" active-text="逐渐探索合适并发" @change="saveExploration" /><p class="field-note">从 1 开始，整轮成功后递增；同类任务变慢或限流时停止增加。</p><div v-if="form.adaptive" class="form-row"><div><label class="field-label">长尾耗时倍率</label><el-input-number v-model="form.slowdown_ratio" :min="1.1" :step="0.5" /></div><div><label class="field-label">最短观察时间（秒）</label><el-input-number v-model="form.min_observation_seconds" :min="0" :step="10" /></div></div></div>
          <div class="estimate"><span>将创建 {{ plannedCount }} 个可恢复项目</span><span>最多同时提交 {{ form.concurrency }} 个</span></div>
          <el-button type="primary" size="large" :loading="submitting" :disabled="!canSubmit" @click="createBatch"><el-icon><VideoPlay /></el-icon>开始批量任务</el-button><p v-if="submitError" class="inline-error">{{ submitError }}</p>
        </section>
        <section class="panel queue-panel">
          <header class="panel-heading"><div><span class="kicker">2 / 实时队列</span><h3>{{ activeBatch ? activeBatch.title : '等待第一批任务' }}</h3></div><div class="queue-actions"><el-button v-if="activeBatch && ['running','queued'].includes(activeBatch.status)" size="small" type="warning" plain @click="pause">暂停后续提交</el-button><el-button v-if="activeBatch && activeBatch.status === 'paused'" size="small" type="primary" plain @click="resume">继续提交</el-button><el-button size="small" plain @click="refresh">刷新</el-button></div></header>
          <template v-if="activeBatch">
            <div class="field-note" role="status">模型 {{ activeBatch.model || '使用已保存默认模型' }} · 当前并发 {{ activeBatch.effective_concurrency || activeBatch.concurrency }} / 上限 {{ activeBatch.concurrency }} · {{ explorationLabel(activeBatch.exploration) }}</div>
            <div class="queue-summary"><div><strong>{{ batchPercent === null ? '阶段制' : batchPercent + '%' }}</strong><span>{{ batchStatusLabel(activeBatch.status) }}</span></div><el-progress :percentage="batchPercent || 0" :show-text="false" :status="activeBatch.failed && !activeBatch.completed ? 'exception' : undefined" /><div class="counts"><span>排队 {{ activeBatch.queued }}</span><span>运行 {{ activeBatch.running }}</span><span>完成 {{ activeBatch.completed }}</span><span>失败 {{ activeBatch.failed }}</span><span v-if="activeBatch.needs_review" class="review-count">待核对 {{ activeBatch.needs_review }}</span></div></div>
            <div v-if="activeBatch.needs_review" class="review-note"><el-icon><Warning /></el-icon><span><strong>有 {{ activeBatch.needs_review }} 项需要先核对</strong><small>这些请求可能已被服务商受理。系统不会自动重试，避免重复生成和扣费。</small></span></div>
            <div class="item-list"><article v-for="item in activeBatch.items" :key="item.id" :class="['queue-item', item.status]"><div class="item-index">{{ item.ordinal + 1 }}</div><div class="item-main"><strong>{{ item.request && item.request.prompt ? item.request.prompt : '项目 ' + (item.ordinal + 1) }}</strong><small v-if="item.download_status === 'waiting_provider'">服务端成片尚未就绪，正在恢复取回</small><small v-else-if="item.error_message" :class="['item-error', { review: batchItemNeedsReview(item) }]">{{ item.error_message }}</small><small v-else>{{ itemStatusLabel(item.status) }}<span v-if="item.attempt"> · 第 {{ item.attempt }} 次</span></small></div><div class="item-preview"><video v-if="item.kind === 'video' && item.media_url" :src="artifactMediaUrlItem(item)" controls preload="metadata" /><img v-else-if="item.kind === 'image' && item.media_url && !broken.has(item.id)" :src="artifactMediaUrlItem(item)" alt="" @error="markBroken(item.id)" /><span v-else :class="{ broken: broken.has(item.id) }"><el-icon><component :is="item.kind === 'video' ? 'VideoCamera' : 'Picture'" /></el-icon></span></div><div class="item-actions"><el-button v-if="batchItemCanRetry(item)" link type="primary" @click="retry(item)">重新排队</el-button><span v-else-if="batchItemNeedsReview(item)" class="reconcile-label">先核对</span><a v-if="item.media_url" :href="artifactMediaUrlItem(item)" target="_blank" rel="noreferrer">打开</a></div></article></div>
            <el-pagination v-if="activeBatch.items_total > itemPageSize" v-model:current-page="itemPage" :page-size="itemPageSize" :total="activeBatch.items_total" layout="prev, pager, next" class="item-pagination" @current-change="loadItemPage" />
          </template>
          <div v-else class="queue-empty"><el-icon><CopyDocument /></el-icon><strong>这里会显示每一项的真实状态</strong><p>提交后可以刷新页面，队列会从本地服务继续。</p></div>
        </section>
      </div>
      <section class="panel history-panel"><header class="panel-heading"><div><span class="kicker">3 / 批次记录</span><h3>最近批量任务</h3></div><router-link to="/history">查看全部历史 <el-icon><ArrowRight /></el-icon></router-link></header><div v-if="batches.length" class="batch-history"><button v-for="batch in batches" :key="batch.id" type="button" :class="{ active: batch.id === activeBatch?.id }" @click="selectBatch(batch.id)"><span><strong>{{ batch.title }}</strong><small>{{ batch.total }} 项 · {{ batch.updated_at ? new Date(batch.updated_at).toLocaleString('zh-CN') : '刚刚' }}</small></span><em :class="batchTone(batch.status)">{{ batchStatusLabel(batch.status) }}</em></button></div><div v-else class="empty-note">还没有批次记录。</div></section>
    </div>
  </div>
</template>

<script setup>
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage } from 'element-plus'
import { ArrowRight, CopyDocument, EditPen, FolderOpened, MagicStick, VideoPlay, Warning } from '@element-plus/icons-vue'
import { useLiveRefresh } from '@/composables/useLiveRefresh'
import { useWorkbenchPage } from '@/composables/useWorkbenchPage'
import mediaBatchAPI from '@/api/mediaBatch'
import { artifactMediaUrl } from '@/utils/mediaUrl'
import { batchItemCanRetry, batchItemNeedsReview, batchRequestKey } from '@/utils/batchRequestKey'
import { aiAPI } from '@/api/ai'
import { batchModelOptions, batchModelSelection } from '@/utils/batchModels'

const savedConcurrency = Number(localStorage.getItem('yinzi-batch-concurrency') || 8)
const route = useRoute()
const selectedBatchId = ref(String(route.query.batch || ''))
let selectionRead = 0
let modelRead = 0
const form = reactive({ kind: 'image', prompt: '', lines: '', count: 8, concurrency: Number.isSafeInteger(savedConcurrency) && savedConcurrency >= 1 ? savedConcurrency : 8, model: '', title: '', adaptive: localStorage.getItem('yinzi-batch-adaptive') === 'true', slowdown_ratio: 2.5, min_observation_seconds: 30, settings: { aspect_ratio: '16:9', duration: 5 } })
const batches = ref([]); const activeBatch = ref(null); const loading = ref(false); const submitting = ref(false); const submitError = ref(''); const error = ref(''); const broken = ref(new Set()); const modelOptions = ref([]); const itemPage = ref(1); const itemPageSize = 50; let timer = null
const plannedCount = computed(() => { const lines = form.lines.split(/\r?\n/).map(v => v.trim()).filter(Boolean); return lines.length || Number(form.count) || 1 })
const canSubmit = computed(() => Boolean(form.prompt.trim() || form.lines.trim()) && plannedCount.value > 0 && Number.isSafeInteger(form.concurrency) && form.concurrency >= 1)
const batchPercent = computed(() => { if (!activeBatch.value?.total) return null; return Math.round((activeBatch.value.completed + activeBatch.value.failed + activeBatch.value.needs_review) / activeBatch.value.total * 100) })
const modelService = computed(() => form.kind === 'video' ? 'video' : 'image')
function saveExploration(value) { localStorage.setItem('yinzi-batch-adaptive', String(value)) }
function explorationLabel(value = {}) { if (value.mode !== 'adaptive') return '固定并发'; return ({ latency_tail: '观察到长尾，保持当前并发', rate_limited: '观察到限流，停止扩容', result_requires_review: '有失败或待核对项，停止扩容', cohort_missing: '探索记录待核对，保持并发', configured_limit: '已达到设置上限' })[value.reason] || '整轮成功后逐步增加' }
function saveConcurrency(value) { const n = Number(value); if (Number.isSafeInteger(n) && n >= 1) localStorage.setItem('yinzi-batch-concurrency', String(n)) }
async function loadModels() {
  const read = ++modelRead
  modelOptions.value = []
  try {
    const result = await aiAPI.list(modelService.value)
    if (read === modelRead) modelOptions.value = batchModelOptions(Array.isArray(result?.items) ? result.items : Array.isArray(result) ? result : [])
  } catch (_) { if (read === modelRead) modelOptions.value = [] }
}
async function refresh() { loading.value = true; error.value = ''; try { const result = await mediaBatchAPI.list({ limit: 30 }); batches.value = result?.items || []; const target = selectedBatchId.value || batches.value[0]?.id; if (target) await selectBatch(target, false, false) } catch (e) { error.value = e?.message || '暂时无法读取批量队列' } finally { loading.value = false } }
async function selectBatch(id, reload = true, resetPage = true) { selectedBatchId.value = String(id); const read = ++selectionRead; try { if (resetPage) itemPage.value = 1; const item = await mediaBatchAPI.get(id, { item_page: itemPage.value, item_page_size: itemPageSize }); if (read !== selectionRead || selectedBatchId.value !== String(id)) return; if (item) activeBatch.value = item; if (reload) { const result = await mediaBatchAPI.list({ limit: 30 }); batches.value = result?.items || [] } } catch (e) { if (read === selectionRead) error.value = e?.message || '暂时无法读取所选批次' } }
async function loadItemPage() { if (activeBatch.value?.id) await selectBatch(activeBatch.value.id, false, false) }
async function createBatch() { submitting.value = true; submitError.value = ''; try { const lines = form.lines.split(/\r?\n/).map(v => v.trim()).filter(Boolean); const count = lines.length || Number(form.count); const selection = batchModelSelection(form.model, modelOptions.value, form.kind); const items = Array.from({ length: count }, (_, index) => ({ prompt: lines[index] || (form.prompt.trim() + '（变体 ' + (index + 1) + '）'), ...selection, aspect_ratio: form.settings.aspect_ratio, duration: form.kind === 'video' ? form.settings.duration : undefined })); const payload = { kind: form.kind, title: form.title || undefined, prompt: form.prompt.trim(), model: selection.model, concurrency: Number(form.concurrency), exploration: { mode: form.adaptive ? 'adaptive' : 'fixed', slowdown_ratio: form.slowdown_ratio, min_observation_ms: form.min_observation_seconds * 1000 }, settings: { ...selection, aspect_ratio: form.settings.aspect_ratio, ...(form.kind === 'video' ? { duration: form.settings.duration } : {}) }, items }; const result = await mediaBatchAPI.create({ ...payload, idempotency_key: batchRequestKey(payload) }); ++selectionRead; activeBatch.value = result; selectedBatchId.value = String(result.id); itemPage.value = 1; await refresh(); ElMessage.success(result?.reused ? '已恢复同一批次，没有重复提交' : '批量任务已创建，队列开始推进') } catch (e) { submitError.value = e?.message || '创建批量任务失败' } finally { submitting.value = false } }
async function updateBatch(action, message) {
  const id = activeBatch.value?.id
  if (!id) return
  const read = ++selectionRead
  try {
    const result = await action(id)
    if (read === selectionRead && selectedBatchId.value === String(id)) activeBatch.value = result
    ElMessage.success(message)
  } catch (e) { ElMessage.error(e?.message || '批次操作暂未完成，请刷新查看') }
}
function pause() { return updateBatch(id => mediaBatchAPI.pause(id), '已暂停后续提交，正在运行的项目会自然收口') }
function resume() { return updateBatch(id => mediaBatchAPI.resume(id), '已继续提交') }
function retry(item) { return updateBatch(id => mediaBatchAPI.retry(id, item.id), '已重新加入队列') }
function markBroken(id) { broken.value = new Set([...broken.value, id]) }
function artifactMediaUrlItem(item) { return artifactMediaUrl({ media_url: item.media_url }) }
function itemStatusLabel(status) { return ({ queued: '等待提交', submitting: '正在提交', processing: '上游处理中', completed: '已完成', failed: '确定失败', needs_review: '等待核对', paused: '已暂停' })[status] || '处理中' }
function batchStatusLabel(status) { return ({ queued: '准备中', running: '执行中', paused: '已暂停', completed: '已完成', partial: '部分完成', failed: '全部失败', needs_review: '有结果待核对' })[status] || '处理中' }
function batchTone(status) { return status === 'completed' ? 'success' : status === 'failed' ? 'danger' : ['paused','partial','needs_review'].includes(status) ? 'warning' : 'active' }
onMounted(loadModels)
watch(() => route.query.batch, value => { if (value) selectBatch(String(value), false) })
useLiveRefresh(refresh, { active: () => Boolean(activeBatch.value && ['running','queued'].includes(activeBatch.value.status)), failed: () => Boolean(error.value) })
watch(() => form.kind, () => { form.model = ''; loadModels() })
onBeforeUnmount(() => { ++modelRead; ++selectionRead; if (timer) window.clearInterval(timer) })
useWorkbenchPage({ refresh: refresh, error: () => error.value, loading: () => loading.value })
</script>

<style scoped>
